const PROMPT_VERSION = 'v2';
const rows = $('Only labeled').all();
const preds = $input.all();

let tp = 0, fp = 0, fn = 0, tn = 0, typeHit = 0, typeN = 0, bad = 0;
const wrong = [];

preds.forEach((p, i) => {
  const src = (rows[i] || {}).json || {};
  let ai = {};
  try {
    const raw = String(p.json.output || p.json.text || '');
    ai = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  } catch (e) { bad++; ai = { event_type: 'parse_error' }; }

  const expEvent = src.expected_type !== 'not_relevant';
  const predEvent = ai.event_type !== 'not_relevant' && ai.event_type !== 'parse_error';

  if (expEvent && predEvent) tp++;
  else if (!expEvent && predEvent) fp++;
  else if (expEvent && !predEvent) fn++;
  else tn++;

  if (expEvent) { typeN++; if (ai.event_type === src.expected_type) typeHit++; }
  if (expEvent !== predEvent) {
    wrong.push((expEvent ? 'MISSED: ' : 'FALSE ALARM: ') + String(src.title || '').slice(0, 70));
  }
});

const n = preds.length;
const pct = (a, b) => b ? Math.round(100 * a / b) + '%' : 'n/a';
const warn = rows.length === n ? '' : '\nWARNING: ' + rows.length + ' rows but ' + n + ' answers, results unreliable.';

const message = (
  'EVALUATION (prompt ' + PROMPT_VERSION + ')\n' +
  'Headlines tested: ' + n + '\n' +
  'Accuracy: ' + pct(tp + tn, n) + '\n' +
  'Precision: ' + pct(tp, tp + fp) + '\n' +
  'Recall: ' + pct(tp, tp + fn) + '\n' +
  'Event type correct: ' + pct(typeHit, typeN) + '\n' +
  'Counts: tp ' + tp + ', fp ' + fp + ', fn ' + fn + ', tn ' + tn + ', unreadable ' + bad +
  warn + '\n\n' +
  (wrong.slice(0, 8).join('\n') || 'No mistakes found.')
).replace(/[*_`\[\]]/g, ' ').slice(0, 3900);

return [{ json: { message, tp, fp, fn, tn, n } }];
